"""Slow down SVG snake animations generated by Platane/snk.

Usage: python scripts/slow_snake.py dist/*.svg
Speed multiplier is editable below: 2.5 means 2.5x longer animation.
"""
from pathlib import Path
import re
import sys

SLOWDOWN = 2.5
PATTERN = re.compile(r'(animation\s*:\s*none\s+linear\s+)(\d+(?:\.\d+)?)(ms\s+infinite)', re.I)

if len(sys.argv) < 2:
    raise SystemExit('Pass one or more generated SVG files')

for name in sys.argv[1:]:
    path = Path(name)
    svg = path.read_text(encoding='utf-8')
    def slow(match):
        return f'{match.group(1)}{round(float(match.group(2)) * SLOWDOWN)}{match.group(3)}'
    updated, count = PATTERN.subn(slow, svg)
    if count == 0:
        raise SystemExit(f'Could not find snake timing in {name}; generator SVG structure may have changed')
    path.write_text(updated, encoding='utf-8')
    print(f'{name}: slowed animation by {SLOWDOWN}x')
